insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Muscle contraction', 'Muscle contraction is the activation of tension-generating sites within muscle cells. In physiology, muscle contraction does not necessarily mean muscle shortening because muscle tension can be produced without changes in muscle length (isometric contraction), such as when holding something heavy in the same position. The termination of muscle contraction is followed by muscle relaxation, which is a return of the muscle fibers to their low tension-generating state. For the contractions to happen, the muscle cells must rely on the interaction of two types of filament: thin and thick filaments. The major constituent of thin filaments is a chain formed by helical coiling of two strands of actin, and thick filaments predominantly consist of chains of the motor-protein myosin. Together, these two filaments form myofibrils - the basic functional organelles in the skeletal muscle system.', 'Wikipedia: Muscle contraction', 'https://en.wikipedia.org/w/index.php?title=Muscle_contraction&oldid=1373020514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Muscle contraction is the activation of tension-generating sites within muscle cells. In physiology, muscle contraction does not necessarily mean muscle shortening because muscle tension can be produced without changes in muscle length (isometric contraction), such as when holding something heavy in the same position. The termination of muscle contraction is followed by muscle relaxation, which is a return of the muscle fibers to their low tension-generating state. For the contractions to happen, the muscle cells must rely on the interaction of two types of filament: thin and thick filaments. The major constituent of thin filaments is a chain formed by helical coiling of two strands of actin, and thick filaments predominantly consist of chains of the motor-protein myosin. Together, these two filaments form myofibrils - the basic functional organelles in the skeletal muscle system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Muscle contraction', 'In vertebrates, skeletal muscle contractions are neurogenic as they require synaptic input from motor neurons. A single motor neuron is able to innervate multiple muscle fibers, thereby causing the fibers to contract at the same time. Once innervated, the protein filaments within each skeletal muscle fiber slide past each other to produce a contraction, which is explained by the sliding filament theory. The contraction produced can be described as a twitch, summation, or tetanus, depending on the frequency of action potentials. In skeletal muscles, muscle tension is at its greatest when the muscle is stretched to an intermediate length as described by the length-tension relationship. Unlike skeletal muscle, the contractions of smooth and cardiac muscles are myogenic (meaning that they are initiated by the smooth or heart muscle cells themselves instead of being stimulated by an outside event such as nerve stimulation), although they can be modulated by stimuli from the autonomic nervous system. The mechanisms of contraction in these muscle tissues are similar to those in skeletal muscle tissues.', 'Wikipedia: Muscle contraction', 'https://en.wikipedia.org/w/index.php?title=Muscle_contraction&oldid=1373020514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'In vertebrates, skeletal muscle contractions are neurogenic as they require synaptic input from motor neurons. A single motor neuron is able to innervate multiple muscle fibers, thereby causing the fibers to contract at the same time. Once innervated, the protein filaments within each skeletal muscle fiber slide past each other to produce a contraction, which is explained by the sliding filament theory. The contraction produced can be described as a twitch, summation, or tetanus, depending on the frequency of action potentials. In skeletal muscles, muscle tension is at its greatest when the muscle is stretched to an intermediate length as described by the length-tension relationship. Unlike skeletal muscle, the contractions of smooth and cardiac muscles are myogenic (meaning that they are initiated by the smooth or heart muscle cells themselves instead of being stimulated by an outside event such as nerve stimulation), although they can be modulated by stimuli from the autonomic nervous system. The mechanisms of contraction in these muscle tissues are similar to those in skeletal muscle tissues.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Muscle contraction', 'Muscle contraction can also be described in terms of two variables: length and tension. In natural movements that underlie locomotor activity, muscle contractions are multifaceted as they are able to produce changes in length and tension in a time-varying manner. Therefore, neither length nor tension is likely to remain the same in skeletal muscles that contract during locomotion. Contractions can be described as isometric if the muscle tension changes but the muscle length remains the same. In contrast, a muscle contraction is described as isotonic if muscle tension remains the same throughout the contraction. If the muscle length shortens, the contraction is concentric; if the muscle length lengthens, the contraction is eccentric.', 'Wikipedia: Muscle contraction', 'https://en.wikipedia.org/w/index.php?title=Muscle_contraction&oldid=1373020514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Muscle contraction can also be described in terms of two variables: length and tension. In natural movements that underlie locomotor activity, muscle contractions are multifaceted as they are able to produce changes in length and tension in a time-varying manner. Therefore, neither length nor tension is likely to remain the same in skeletal muscles that contract during locomotion. Contractions can be described as isometric if the muscle tension changes but the muscle length remains the same. In contrast, a muscle contraction is described as isotonic if muscle tension remains the same throughout the contraction. If the muscle length shortens, the contraction is concentric; if the muscle length lengthens, the contraction is eccentric.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Muscle contraction: Types', 'Muscle contractions can be described based on two variables: force and length. Force itself can be differentiated as either tension or load. Muscle tension is the force exerted by the muscle on an object whereas a load is the force exerted by an object on the muscle. When muscle tension changes without any corresponding changes in muscle length, the muscle contraction is described as isometric. If the muscle length changes while muscle tension remains the same, then the muscle contraction is isotonic. In an isotonic contraction, the muscle length can either shorten to produce a concentric contraction or lengthen to produce an eccentric contraction. In natural movements that underlie locomotor activity, muscle contractions are multifaceted as they are able to produce changes in length and tension in a time-varying manner. Therefore, neither length nor tension is likely to remain constant when the muscle is active during locomotor activity.', 'Wikipedia: Muscle contraction', 'https://en.wikipedia.org/w/index.php?title=Muscle_contraction&oldid=1373020514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Muscle contractions can be described based on two variables: force and length. Force itself can be differentiated as either tension or load. Muscle tension is the force exerted by the muscle on an object whereas a load is the force exerted by an object on the muscle. When muscle tension changes without any corresponding changes in muscle length, the muscle contraction is described as isometric. If the muscle length changes while muscle tension remains the same, then the muscle contraction is isotonic. In an isotonic contraction, the muscle length can either shorten to produce a concentric contraction or lengthen to produce an eccentric contraction. In natural movements that underlie locomotor activity, muscle contractions are multifaceted as they are able to produce changes in length and tension in a time-varying manner. Therefore, neither length nor tension is likely to remain constant when the muscle is active during locomotor activity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Muscle contraction: Isometric contraction', 'An isometric contraction of a muscle generates tension without changing length. An example can be found when the muscles of the hand and forearm grip an object; the joints of the hand do not move, but muscles generate sufficient force to prevent the object from being dropped.', 'Wikipedia: Muscle contraction', 'https://en.wikipedia.org/w/index.php?title=Muscle_contraction&oldid=1373020514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'An isometric contraction of a muscle generates tension without changing length. An example can be found when the muscles of the hand and forearm grip an object; the joints of the hand do not move, but muscles generate sufficient force to prevent the object from being dropped.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Muscle contraction: Isotonic contraction', 'In isotonic contraction, the tension in the muscle remains constant despite a change in muscle length. This occurs when a muscle''s force of contraction matches the total load on the muscle.', 'Wikipedia: Muscle contraction', 'https://en.wikipedia.org/w/index.php?title=Muscle_contraction&oldid=1373020514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'In isotonic contraction, the tension in the muscle remains constant despite a change in muscle length. This occurs when a muscle''s force of contraction matches the total load on the muscle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Muscle contraction: Concentric contraction', 'In concentric contraction, muscle tension is sufficient to overcome the load, and the muscle shortens as it contracts. This occurs when the force generated by the muscle exceeds the load opposing its contraction. During a concentric contraction, a muscle is stimulated to contract according to the sliding filament theory. This occurs throughout the length of the muscle, generating a force at the origin and insertion, causing the muscle to shorten and changing the angle of the joint. In relation to the elbow, a concentric contraction of the biceps would cause the arm to bend at the elbow as the hand moved from the leg to the shoulder (a biceps curl). A concentric contraction of the triceps would change the angle of the joint in the opposite direction, straightening the arm and moving the hand towards the leg.', 'Wikipedia: Muscle contraction', 'https://en.wikipedia.org/w/index.php?title=Muscle_contraction&oldid=1373020514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'In concentric contraction, muscle tension is sufficient to overcome the load, and the muscle shortens as it contracts. This occurs when the force generated by the muscle exceeds the load opposing its contraction. During a concentric contraction, a muscle is stimulated to contract according to the sliding filament theory. This occurs throughout the length of the muscle, generating a force at the origin and insertion, causing the muscle to shorten and changing the angle of the joint. In relation to the elbow, a concentric contraction of the biceps would cause the arm to bend at the elbow as the hand moved from the leg to the shoulder (a biceps curl). A concentric contraction of the triceps would change the angle of the joint in the opposite direction, straightening the arm and moving the hand towards the leg.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Muscle contraction: Eccentric contraction', 'In eccentric contraction, the tension generated while isometric is insufficient to overcome the external load on the muscle and the muscle fibers lengthen as they contract. Rather than working to pull a joint in the direction of the muscle contraction, the muscle acts to decelerate the joint at the end of a movement or otherwise control the repositioning of a load. This can occur involuntarily (e.g., when attempting to move a weight too heavy for the muscle to lift) or voluntarily (e.g., when the muscle is ''smoothing out'' a movement or resisting gravity such as during downhill walking). Over the short-term, strength training involving both eccentric and concentric contractions appear to increase muscular strength more than training with concentric contractions alone. However, exercise-induced muscle damage is also greater during lengthening contractions. During an eccentric contraction of the biceps muscle, the elbow starts the movement while bent and then straightens as the hand moves away from the shoulder. During an eccentric contraction of the triceps muscle, the elbow starts the movement straight and then bends as the hand moves towards the shoulder. Desmin, titin, and other z-line proteins are involved in eccentric contractions, but their mechanism is poorly understood in comparison to cross-bridge cycling in concentric contractions.', 'Wikipedia: Muscle contraction', 'https://en.wikipedia.org/w/index.php?title=Muscle_contraction&oldid=1373020514', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'In eccentric contraction, the tension generated while isometric is insufficient to overcome the external load on the muscle and the muscle fibers lengthen as they contract. Rather than working to pull a joint in the direction of the muscle contraction, the muscle acts to decelerate the joint at the end of a movement or otherwise control the repositioning of a load. This can occur involuntarily (e.g., when attempting to move a weight too heavy for the muscle to lift) or voluntarily (e.g., when the muscle is ''smoothing out'' a movement or resisting gravity such as during downhill walking). Over the short-term, strength training involving both eccentric and concentric contractions appear to increase muscular strength more than training with concentric contractions alone. However, exercise-induced muscle damage is also greater during lengthening contractions. During an eccentric contraction of the biceps muscle, the elbow starts the movement while bent and then straightens as the hand moves away from the shoulder. During an eccentric contraction of the triceps muscle, the elbow starts the movement straight and then bends as the hand moves towards the shoulder. Desmin, titin, and other z-line proteins are involved in eccentric contractions, but their mechanism is poorly understood in comparison to cross-bridge cycling in concentric contractions.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Sliding filament theory', 'The sliding filament theory explains the mechanism of muscle contraction based on muscle proteins that slide past each other to generate movement. According to the sliding filament theory, the myosin (thick filaments) of muscle fibers slide past the actin (thin filaments) during muscle contraction, while the two groups of filaments remain at relatively constant length. The theory was independently introduced in 1954 by two research teams, one consisting of Andrew Huxley and Rolf Niedergerke from the University of Cambridge, and the other consisting of Hugh Huxley and Jean Hanson from the Massachusetts Institute of Technology. It was originally conceived by Hugh Huxley in 1953. Andrew Huxley and Niedergerke introduced it as a "very attractive" hypothesis. Before the 1950s, there were several competing theories on muscle contraction, including electrical attraction, protein folding, and protein modification. The novel theory directly introduced a new concept called cross-bridge theory (classically swinging cross-bridge, now mostly referred to as cross-bridge cycle) which explains the molecular mechanism of sliding filament. Cross-bridge theory states that actin and myosin form a protein complex (classically called actomyosin) by attachment of myosin head on the actin filament, thereby forming a sort of cross-bridge between the two filaments. The sliding filament theory is a widely accepted explanation of the mechanism that underlies muscle contraction.', 'Wikipedia: Sliding filament theory', 'https://en.wikipedia.org/w/index.php?title=Sliding_filament_theory&oldid=1378988613', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The sliding filament theory explains the mechanism of muscle contraction based on muscle proteins that slide past each other to generate movement. According to the sliding filament theory, the myosin (thick filaments) of muscle fibers slide past the actin (thin filaments) during muscle contraction, while the two groups of filaments remain at relatively constant length. The theory was independently introduced in 1954 by two research teams, one consisting of Andrew Huxley and Rolf Niedergerke from the University of Cambridge, and the other consisting of Hugh Huxley and Jean Hanson from the Massachusetts Institute of Technology. It was originally conceived by Hugh Huxley in 1953. Andrew Huxley and Niedergerke introduced it as a "very attractive" hypothesis. Before the 1950s, there were several competing theories on muscle contraction, including electrical attraction, protein folding, and protein modification. The novel theory directly introduced a new concept called cross-bridge theory (classically swinging cross-bridge, now mostly referred to as cross-bridge cycle) which explains the molecular mechanism of sliding filament. Cross-bridge theory states that actin and myosin form a protein complex (classically called actomyosin) by attachment of myosin head on the actin filament, thereby forming a sort of cross-bridge between the two filaments. The sliding filament theory is a widely accepted explanation of the mechanism that underlies muscle contraction.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Sliding filament theory: The sliding filament theory', 'The sliding filament theory was born from two consecutive papers published on the 22 May 1954 issue of Nature under the common theme "Structural Changes in Muscle During Contraction". Though their conclusions were fundamentally similar, their underlying experimental data and propositions were different.', 'Wikipedia: Sliding filament theory', 'https://en.wikipedia.org/w/index.php?title=Sliding_filament_theory&oldid=1378988613', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The sliding filament theory was born from two consecutive papers published on the 22 May 1954 issue of Nature under the common theme "Structural Changes in Muscle During Contraction". Though their conclusions were fundamentally similar, their underlying experimental data and propositions were different.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Sliding filament theory: Huxley-Niedergerke hypothesis', 'The first paper, written by Andrew Huxley and Rolf Niedergerke, is titled "Interference microscopy of living muscle fibres". It was based on their study of frog muscle using interference microscope, which Andrew Huxley developed for the purpose. According to them: the I bands are composed of actin filaments, and the A bands principally of myosin filaments; and during contraction, the actin filaments move into the A bands between the myosin filaments.', 'Wikipedia: Sliding filament theory', 'https://en.wikipedia.org/w/index.php?title=Sliding_filament_theory&oldid=1378988613', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The first paper, written by Andrew Huxley and Rolf Niedergerke, is titled "Interference microscopy of living muscle fibres". It was based on their study of frog muscle using interference microscope, which Andrew Huxley developed for the purpose. According to them: the I bands are composed of actin filaments, and the A bands principally of myosin filaments; and during contraction, the actin filaments move into the A bands between the myosin filaments.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Sliding filament theory: Huxley-Hanson hypothesis', 'The second paper, by Hugh Huxley and Jean Hanson, is titled "Changes in the cross-striations of muscle during contraction and stretch and their structural interpretation". It is more elaborate and was based on their study of rabbit muscle using phase contrast and electron microscopes. According to them: the backbone of a muscle fibre is actin filaments which extend from the Z line up to one end of the H zone, where they are attached to an elastic component which they named "S filament"; myosin filaments extend from one end of the A band through the H zone up to the other end of the A band; myosin filaments remain in relatively constant length during muscle stretch or contraction; if myosin filaments contract beyond the length of the A band, their ends fold up to form contraction bands; myosin and actin filaments lie side by side in the A band and in the absence of ATP they do not form cross-linkages; during stretching, only the I bands and H zone increase in length, while A bands remain the same; during contraction, actin filaments move into the A bands and the H zone is filled up reducing its stretch, the I bands shorten, the Z line comes in contact with the A bands; and', 'Wikipedia: Sliding filament theory', 'https://en.wikipedia.org/w/index.php?title=Sliding_filament_theory&oldid=1378988613', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The second paper, by Hugh Huxley and Jean Hanson, is titled "Changes in the cross-striations of muscle during contraction and stretch and their structural interpretation". It is more elaborate and was based on their study of rabbit muscle using phase contrast and electron microscopes. According to them: the backbone of a muscle fibre is actin filaments which extend from the Z line up to one end of the H zone, where they are attached to an elastic component which they named "S filament"; myosin filaments extend from one end of the A band through the H zone up to the other end of the A band; myosin filaments remain in relatively constant length during muscle stretch or contraction; if myosin filaments contract beyond the length of the A band, their ends fold up to form contraction bands; myosin and actin filaments lie side by side in the A band and in the absence of ATP they do not form cross-linkages; during stretching, only the I bands and H zone increase in length, while A bands remain the same; during contraction, actin filaments move into the A bands and the H zone is filled up reducing its stretch, the I bands shorten, the Z line comes in contact with the A bands; and');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Sliding filament theory: Huxley-Hanson hypothesis', 'the possible driving force of contraction is the actin-myosin linkages which depend on ATP hydrolysis by the myosin.', 'Wikipedia: Sliding filament theory', 'https://en.wikipedia.org/w/index.php?title=Sliding_filament_theory&oldid=1378988613', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'the possible driving force of contraction is the actin-myosin linkages which depend on ATP hydrolysis by the myosin.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Sliding filament theory: Reception and consequences', 'In spite of strong evidence, the sliding filament theory did not gain any support for several years to come. Szent-Györgyi himself refused to believe that myosin filaments were confined to the thick filament (A band). F.O. Schmitt, whose electron microscope provided the best data, also remained sceptical of the original images. There were also immediate arguments as to the organisation of the filaments, whether the two sets (myosin and actin) of filaments were merely overlapping or continuous. It was only with the new electron microscope that Hugh Huxley confirmed the overlapping nature of the filaments in 1957. It was also from this publication that the existence of actin-myosin linkage (now called cross-bridge) was clearly shown. But he took another five years to provide evidence that the cross-bridge was a dynamic interaction between actin and myosin filaments. He obtained the actual molecular arrangement of the filaments using X-ray crystallography by teaming up with Kenneth Holmes, who was trained by Rosalind Franklin, in 1965. It was only after a conference in 1972 at Cold Spring Harbor Laboratory, where the theory and its evidence were deliberated, that it became generally accepted. At the conference, as Koscak Maruyama later recalled, Hanson had to answer the criticisms by shouting, "I know I cannot explain the mechanism yet, but the sliding is a fact." The factual proofs came in the early 1980s when it could be demonstrated the actual sliding motion using novel sophisticated tools by different researchers.', 'Wikipedia: Sliding filament theory', 'https://en.wikipedia.org/w/index.php?title=Sliding_filament_theory&oldid=1378988613', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'In spite of strong evidence, the sliding filament theory did not gain any support for several years to come. Szent-Györgyi himself refused to believe that myosin filaments were confined to the thick filament (A band). F.O. Schmitt, whose electron microscope provided the best data, also remained sceptical of the original images. There were also immediate arguments as to the organisation of the filaments, whether the two sets (myosin and actin) of filaments were merely overlapping or continuous. It was only with the new electron microscope that Hugh Huxley confirmed the overlapping nature of the filaments in 1957. It was also from this publication that the existence of actin-myosin linkage (now called cross-bridge) was clearly shown. But he took another five years to provide evidence that the cross-bridge was a dynamic interaction between actin and myosin filaments. He obtained the actual molecular arrangement of the filaments using X-ray crystallography by teaming up with Kenneth Holmes, who was trained by Rosalind Franklin, in 1965. It was only after a conference in 1972 at Cold Spring Harbor Laboratory, where the theory and its evidence were deliberated, that it became generally accepted. At the conference, as Koscak Maruyama later recalled, Hanson had to answer the criticisms by shouting, "I know I cannot explain the mechanism yet, but the sliding is a fact." The factual proofs came in the early 1980s when it could be demonstrated the actual sliding motion using novel sophisticated tools by different researchers.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Sliding filament theory: Cross-bridge mechanism', 'With substantial evidence, Hugh Huxley formally proposed the mechanism for sliding filament which is variously called swinging cross-bridge model, cross-bridge theory or cross-bridge model. (He himself preferred the name "swinging crossbridge model", because, as he recalled, "it [the discovery] was, after all, the 1960s".) He published his theory in the 20 June 1969 issue of Science under the title "The Mechanism of Muscular Contraction". According to his theory, filament sliding occurs by cyclic attachment and detachment of myosin on actin filaments. Contraction occurs when the myosin pulls the actin filament towards the centre of the A band, detaches from actin and creates a force (stroke) to bind to the next actin molecule. This idea was subsequently proven in detail, and is more appropriately known as the cross-bridge cycle.', 'Wikipedia: Sliding filament theory', 'https://en.wikipedia.org/w/index.php?title=Sliding_filament_theory&oldid=1378988613', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'With substantial evidence, Hugh Huxley formally proposed the mechanism for sliding filament which is variously called swinging cross-bridge model, cross-bridge theory or cross-bridge model. (He himself preferred the name "swinging crossbridge model", because, as he recalled, "it [the discovery] was, after all, the 1960s".) He published his theory in the 20 June 1969 issue of Science under the title "The Mechanism of Muscular Contraction". According to his theory, filament sliding occurs by cyclic attachment and detachment of myosin on actin filaments. Contraction occurs when the myosin pulls the actin filament towards the centre of the A band, detaches from actin and creates a force (stroke) to bind to the next actin molecule. This idea was subsequently proven in detail, and is more appropriately known as the cross-bridge cycle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Skeletal muscle', 'Skeletal muscle (commonly referred to as muscle) is one of the three types of vertebrate muscle tissue, the others being cardiac muscle and smooth muscle. They are part of the musculoskeletal system, and typically are attached by tendons to the bones of a skeleton. The skeletal muscle cells (myocytes) are much longer than in the other types of muscle tissue, and are also known as muscle fibers. The tissue of a skeletal muscle is striated – having a striped appearance due to the arrangement of the sarcomeres. A skeletal muscle contains multiple fascicles – bundles of muscle fibers. Each individual fiber and each muscle is surrounded by a type of connective tissue layer of fascia. Muscle fibers are formed from the fusion of developmental myoblasts in a process known as myogenesis resulting in long multinucleated cells. In these cells, the nuclei, termed myonuclei, are located along the inside of the cell membrane. Muscle fibers also have multiple mitochondria to meet energy needs.', 'Wikipedia: Skeletal muscle', 'https://en.wikipedia.org/w/index.php?title=Skeletal_muscle&oldid=1375365422', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Skeletal muscle (commonly referred to as muscle) is one of the three types of vertebrate muscle tissue, the others being cardiac muscle and smooth muscle. They are part of the musculoskeletal system, and typically are attached by tendons to the bones of a skeleton. The skeletal muscle cells (myocytes) are much longer than in the other types of muscle tissue, and are also known as muscle fibers. The tissue of a skeletal muscle is striated – having a striped appearance due to the arrangement of the sarcomeres. A skeletal muscle contains multiple fascicles – bundles of muscle fibers. Each individual fiber and each muscle is surrounded by a type of connective tissue layer of fascia. Muscle fibers are formed from the fusion of developmental myoblasts in a process known as myogenesis resulting in long multinucleated cells. In these cells, the nuclei, termed myonuclei, are located along the inside of the cell membrane. Muscle fibers also have multiple mitochondria to meet energy needs.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Skeletal muscle', 'Muscle fibers are in turn composed of myofibrils. The myofibrils are composed of actin and myosin filaments called myofilaments, repeated in units called sarcomeres, which are the basic functional, contractile units of the muscle fiber necessary for muscle contraction. Muscles are predominantly powered by the oxidation of fats and carbohydrates, but anaerobic chemical reactions are also used, particularly by fast twitch fibers. These chemical reactions produce adenosine triphosphate (ATP) molecules that are used to power the movement of the myosin heads. Skeletal muscle comprises about 35% of the human body by weight. The functions of skeletal muscle include producing movement, maintaining body posture, controlling body temperature, and stabilizing joints. Skeletal muscle is also an endocrine organ. Under different physiological conditions, subsets of 654 different proteins as well as lipids, amino acids, metabolites and small RNAs are found in the secretome of skeletal muscles.', 'Wikipedia: Skeletal muscle', 'https://en.wikipedia.org/w/index.php?title=Skeletal_muscle&oldid=1375365422', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Muscle fibers are in turn composed of myofibrils. The myofibrils are composed of actin and myosin filaments called myofilaments, repeated in units called sarcomeres, which are the basic functional, contractile units of the muscle fiber necessary for muscle contraction. Muscles are predominantly powered by the oxidation of fats and carbohydrates, but anaerobic chemical reactions are also used, particularly by fast twitch fibers. These chemical reactions produce adenosine triphosphate (ATP) molecules that are used to power the movement of the myosin heads. Skeletal muscle comprises about 35% of the human body by weight. The functions of skeletal muscle include producing movement, maintaining body posture, controlling body temperature, and stabilizing joints. Skeletal muscle is also an endocrine organ. Under different physiological conditions, subsets of 654 different proteins as well as lipids, amino acids, metabolites and small RNAs are found in the secretome of skeletal muscles.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Skeletal muscle', 'Skeletal muscles are substantially composed of multinucleated contractile muscle fibers (myocytes). Considerable numbers of resident and infiltrating mononuclear cells are also present. In terms of volume, myocytes make up the great majority of skeletal muscle. Skeletal muscle myocytes are usually very large, being about 2–3 cm long and 100 μm in diameter. By comparison, the mononuclear cells in muscles are much smaller. Some of the mononuclear cells in muscles are endothelial cells (which are about 50–70 μm long, 10–30 μm wide and 0.1–10 μm thick), macrophages (21 μm in diameter) and neutrophils (12-15 μm in diameter). However, in terms of nuclei present in skeletal muscle, myocyte nuclei (myonuclei) may be only half of the nuclei present, while nuclei from resident and infiltrating mononuclear cells make up the other half. Considerable research on skeletal muscle is focused on the muscle fibers. Interest has also focused on the different types of mononuclear cells of skeletal muscle, as well as on the endocrine functions of muscle.', 'Wikipedia: Skeletal muscle', 'https://en.wikipedia.org/w/index.php?title=Skeletal_muscle&oldid=1375365422', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Skeletal muscles are substantially composed of multinucleated contractile muscle fibers (myocytes). Considerable numbers of resident and infiltrating mononuclear cells are also present. In terms of volume, myocytes make up the great majority of skeletal muscle. Skeletal muscle myocytes are usually very large, being about 2–3 cm long and 100 μm in diameter. By comparison, the mononuclear cells in muscles are much smaller. Some of the mononuclear cells in muscles are endothelial cells (which are about 50–70 μm long, 10–30 μm wide and 0.1–10 μm thick), macrophages (21 μm in diameter) and neutrophils (12-15 μm in diameter). However, in terms of nuclei present in skeletal muscle, myocyte nuclei (myonuclei) may be only half of the nuclei present, while nuclei from resident and infiltrating mononuclear cells make up the other half. Considerable research on skeletal muscle is focused on the muscle fibers. Interest has also focused on the different types of mononuclear cells of skeletal muscle, as well as on the endocrine functions of muscle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Skeletal muscle: Gross anatomy', 'There are more than 600 skeletal muscles in the human body, making up around 40% of body weight in healthy young adults. In Western populations, men have on average around 61% more skeletal muscle than women. Most muscles occur in bilaterally-placed pairs to serve both sides of the body. Muscles are often classed as groups of muscles that work together to carry out an action. In the torso there are several major muscle groups including the pectoral, and abdominal muscles; intrinsic and extrinsic muscles are subdivisions of muscle groups in the hand, foot, tongue, and extraocular muscles of the eye. Muscles are also grouped into compartments including four groups in the arm, Apart from the contractile part of a muscle consisting of its fibers, a muscle contains a non-contractile part of dense fibrous connective tissue that makes up the tendon at each end. The tendons attach the muscles to bones to give skeletal movement. The length of a muscle includes the tendons. Connective tissue is present in all muscles as deep fascia. Deep fascia specialises within muscles to enclose each muscle fiber as endomysium; each muscle fascicle as perimysium, and each individual muscle as epimysium. Together these layers are called mysia. Deep fascia also separates the groups of muscles into muscle compartments.', 'Wikipedia: Skeletal muscle', 'https://en.wikipedia.org/w/index.php?title=Skeletal_muscle&oldid=1375365422', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'There are more than 600 skeletal muscles in the human body, making up around 40% of body weight in healthy young adults. In Western populations, men have on average around 61% more skeletal muscle than women. Most muscles occur in bilaterally-placed pairs to serve both sides of the body. Muscles are often classed as groups of muscles that work together to carry out an action. In the torso there are several major muscle groups including the pectoral, and abdominal muscles; intrinsic and extrinsic muscles are subdivisions of muscle groups in the hand, foot, tongue, and extraocular muscles of the eye. Muscles are also grouped into compartments including four groups in the arm, Apart from the contractile part of a muscle consisting of its fibers, a muscle contains a non-contractile part of dense fibrous connective tissue that makes up the tendon at each end. The tendons attach the muscles to bones to give skeletal movement. The length of a muscle includes the tendons. Connective tissue is present in all muscles as deep fascia. Deep fascia specialises within muscles to enclose each muscle fiber as endomysium; each muscle fascicle as perimysium, and each individual muscle as epimysium. Together these layers are called mysia. Deep fascia also separates the groups of muscles into muscle compartments.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Skeletal muscle: Gross anatomy', 'Two types of sensory receptors found in muscles are muscle spindles, and Golgi tendon organs. Muscle spindles are stretch receptors located in the muscle belly. Golgi tendon organs are proprioceptors located at the myotendinous junction that inform of a muscle''s tension.', 'Wikipedia: Skeletal muscle', 'https://en.wikipedia.org/w/index.php?title=Skeletal_muscle&oldid=1375365422', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Two types of sensory receptors found in muscles are muscle spindles, and Golgi tendon organs. Muscle spindles are stretch receptors located in the muscle belly. Golgi tendon organs are proprioceptors located at the myotendinous junction that inform of a muscle''s tension.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Skeletal muscle: Skeletal muscle cells', 'Skeletal muscle cells, also called muscle fibers are the individual contractile cells within a muscle. A single muscle such as the biceps in a young adult male contains around 253,000 muscle fibers. Skeletal muscle fibers are multinucleated with the nuclei often referred to as myonuclei. This occurs during myogenesis with the fusion of myoblasts each contributing a nucleus. Fusion depends on muscle-specific proteins known as fusogens called myomaker and myomerger. Many nuclei are needed by the skeletal muscle cell for the large amounts of proteins and enzymes needed to be produced for the cell''s normal functioning. A single muscle fiber can contain from hundreds to thousands of nuclei. A muscle fiber for example in the human biceps with a length of 10 cm can have as many as 3,000 nuclei. Unlike in a non-muscle cell where the nucleus is centrally positioned, the myonucleus is elongated and located close to the sarcolemma (membrane). The myonuclei are quite uniformly arranged along the fiber with each nucleus having its own myonuclear domain where it is responsible for supporting the volume of cytoplasm in that particular section of the myofiber.', 'Wikipedia: Skeletal muscle', 'https://en.wikipedia.org/w/index.php?title=Skeletal_muscle&oldid=1375365422', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Skeletal muscle cells, also called muscle fibers are the individual contractile cells within a muscle. A single muscle such as the biceps in a young adult male contains around 253,000 muscle fibers. Skeletal muscle fibers are multinucleated with the nuclei often referred to as myonuclei. This occurs during myogenesis with the fusion of myoblasts each contributing a nucleus. Fusion depends on muscle-specific proteins known as fusogens called myomaker and myomerger. Many nuclei are needed by the skeletal muscle cell for the large amounts of proteins and enzymes needed to be produced for the cell''s normal functioning. A single muscle fiber can contain from hundreds to thousands of nuclei. A muscle fiber for example in the human biceps with a length of 10 cm can have as many as 3,000 nuclei. Unlike in a non-muscle cell where the nucleus is centrally positioned, the myonucleus is elongated and located close to the sarcolemma (membrane). The myonuclei are quite uniformly arranged along the fiber with each nucleus having its own myonuclear domain where it is responsible for supporting the volume of cytoplasm in that particular section of the myofiber.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Skeletal muscle: Skeletal muscle cells', 'A group of muscle stem cells known as myosatellite cells, also satellite cells are found between the basement membrane and the sarcolemma of muscle fibers. These cells are normally quiescent but can be activated by exercise or pathology to provide additional myonuclei for muscle growth or repair. Other progenitors for non-myogenic (mononuclear) cells are present in the interstitial space as fibro-adipogenic progenitors (FAPs) which can differentiate into fibroblasts, osteoblasts, and adipocytes. FAPs are distinct from MSCs by the lack of expression of PAX7. Nuclei present in skeletal muscle are about 50% myocyte nuclei and 50% mononuclear cell nuclei. Mononuclear cell types include capillary endothelial cells (45%), fibro-adipogenic progenitors (FAPs)(20%), pericytes (14%) and endothelial-like pericytes (4%). Another 9% of mononuclear cells are muscle stem cells, adjacent to muscle fiber cells. B-cells and T-cells (3%) and macrophages (2%). Each cell type expresses different sets of genes. In a biopsy of human thigh skeletal muscle, there are 13,026 to 13,108 genes with detected expression.', 'Wikipedia: Skeletal muscle', 'https://en.wikipedia.org/w/index.php?title=Skeletal_muscle&oldid=1375365422', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'A group of muscle stem cells known as myosatellite cells, also satellite cells are found between the basement membrane and the sarcolemma of muscle fibers. These cells are normally quiescent but can be activated by exercise or pathology to provide additional myonuclei for muscle growth or repair. Other progenitors for non-myogenic (mononuclear) cells are present in the interstitial space as fibro-adipogenic progenitors (FAPs) which can differentiate into fibroblasts, osteoblasts, and adipocytes. FAPs are distinct from MSCs by the lack of expression of PAX7. Nuclei present in skeletal muscle are about 50% myocyte nuclei and 50% mononuclear cell nuclei. Mononuclear cell types include capillary endothelial cells (45%), fibro-adipogenic progenitors (FAPs)(20%), pericytes (14%) and endothelial-like pericytes (4%). Another 9% of mononuclear cells are muscle stem cells, adjacent to muscle fiber cells. B-cells and T-cells (3%) and macrophages (2%). Each cell type expresses different sets of genes. In a biopsy of human thigh skeletal muscle, there are 13,026 to 13,108 genes with detected expression.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Skeletal muscle: Attachment to tendons', 'Muscles attach to tendons in a complex interface region known as the musculotendinous junction, also known as the myotendinous junction, an area specialised for the primary transmission of force. At the muscle-tendon interface, force is transmitted from the sarcomeres in the muscle cells to the tendon. Muscles and tendons develop in close association, and after their joining at the myotendinous junction they constitute a dynamic unit for the transmission of force from muscle contraction to the skeletal system.', 'Wikipedia: Skeletal muscle', 'https://en.wikipedia.org/w/index.php?title=Skeletal_muscle&oldid=1375365422', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Muscles attach to tendons in a complex interface region known as the musculotendinous junction, also known as the myotendinous junction, an area specialised for the primary transmission of force. At the muscle-tendon interface, force is transmitted from the sarcomeres in the muscle cells to the tendon. Muscles and tendons develop in close association, and after their joining at the myotendinous junction they constitute a dynamic unit for the transmission of force from muscle contraction to the skeletal system.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone', 'A bone is a rigid organ that constitutes part of the skeleton in most vertebrate animals. Bones protect the organs of the body, produce red and white blood cells, store minerals, help regulate acid-base homeostasis, provide structure and support for the body, and enable mobility and hearing. Bones come in a variety of shapes and sizes and have complex internal and external structures. Bone tissue (also known as osseous tissue or bone in the uncountable) is a form of hard tissue, specialised connective tissue that is mineralized and has an intercellular honeycomb-like matrix, which helps to give the bone rigidity. Bone tissue is made up of different types of bone cells: osteoblasts and osteocytes (which form and mineralise bone respectively), osteoclasts (which resorb bone), and modified or flattened osteoblasts (lining cells that form a protective layer on the bone surface). The mineralised matrix of bone tissue has an organic component of mainly ossein, a form of collagen, and an inorganic component of bone mineral, made up of various salts. Bone tissue comprises cortical (compact) bone and cancellous (spongy) bone, although bones may also contain other kinds of tissue including bone marrow, endosteum, periosteum, nerves, blood vessels, and cartilage.', 'Wikipedia: Bone', 'https://en.wikipedia.org/w/index.php?title=Bone&oldid=1380119203', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'A bone is a rigid organ that constitutes part of the skeleton in most vertebrate animals. Bones protect the organs of the body, produce red and white blood cells, store minerals, help regulate acid-base homeostasis, provide structure and support for the body, and enable mobility and hearing. Bones come in a variety of shapes and sizes and have complex internal and external structures. Bone tissue (also known as osseous tissue or bone in the uncountable) is a form of hard tissue, specialised connective tissue that is mineralized and has an intercellular honeycomb-like matrix, which helps to give the bone rigidity. Bone tissue is made up of different types of bone cells: osteoblasts and osteocytes (which form and mineralise bone respectively), osteoclasts (which resorb bone), and modified or flattened osteoblasts (lining cells that form a protective layer on the bone surface). The mineralised matrix of bone tissue has an organic component of mainly ossein, a form of collagen, and an inorganic component of bone mineral, made up of various salts. Bone tissue comprises cortical (compact) bone and cancellous (spongy) bone, although bones may also contain other kinds of tissue including bone marrow, endosteum, periosteum, nerves, blood vessels, and cartilage.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone', 'In the human body at birth, approximately 300 bones are present. Many of these fuse together during development, leaving a total of 206 separate bones in the adult, not counting numerous small sesamoid bones. The largest bone in the body is the femur or thigh-bone, and the smallest is the stapes in the middle ear. The Ancient Greek word for bone is ὀστέον ("osteon"). In anatomical terminology, including in the Terminologia Anatomica, the word for a bone is os (for example, os breve, os longum, os sesamoideum). (This is not to be confused with the alternative medical use of os to mean orifice, from the Latin ōs, mouth.)', 'Wikipedia: Bone', 'https://en.wikipedia.org/w/index.php?title=Bone&oldid=1380119203', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'In the human body at birth, approximately 300 bones are present. Many of these fuse together during development, leaving a total of 206 separate bones in the adult, not counting numerous small sesamoid bones. The largest bone in the body is the femur or thigh-bone, and the smallest is the stapes in the middle ear. The Ancient Greek word for bone is ὀστέον ("osteon"). In anatomical terminology, including in the Terminologia Anatomica, the word for a bone is os (for example, os breve, os longum, os sesamoideum). (This is not to be confused with the alternative medical use of os to mean orifice, from the Latin ōs, mouth.)');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone: Gross anatomy', 'Five types of bones are found in the human body: long, short, flat, irregular, and sesamoid. Long bones are characterized by a shaft, the diaphysis, that is much longer than its width; and by an epiphysis, a rounded head at each end of the shaft. They are made up mostly of compact bone, with lesser amounts of marrow, located within the medullary cavity, and areas of spongy, cancellous bone at the ends of the bones. Most bones of the limbs, including those of the fingers and toes, are long bones. The exceptions are the eight carpal bones of the wrist, the seven articulating tarsal bones of the ankle and the sesamoid bone of the kneecap. Long bones such as the clavicle, that have a differently shaped shaft or ends are also called modified long bones. Short bones are roughly cube-shaped, and have only a thin layer of compact bone surrounding a spongy interior. Short bones provide stability and support as well as some limited motion. Flat bones are thin and generally curved, with two parallel layers of compact bone sandwiching a layer of spongy bone. Most of the bones of the skull are flat bones, as is the sternum.', 'Wikipedia: Bone', 'https://en.wikipedia.org/w/index.php?title=Bone&oldid=1380119203', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Five types of bones are found in the human body: long, short, flat, irregular, and sesamoid. Long bones are characterized by a shaft, the diaphysis, that is much longer than its width; and by an epiphysis, a rounded head at each end of the shaft. They are made up mostly of compact bone, with lesser amounts of marrow, located within the medullary cavity, and areas of spongy, cancellous bone at the ends of the bones. Most bones of the limbs, including those of the fingers and toes, are long bones. The exceptions are the eight carpal bones of the wrist, the seven articulating tarsal bones of the ankle and the sesamoid bone of the kneecap. Long bones such as the clavicle, that have a differently shaped shaft or ends are also called modified long bones. Short bones are roughly cube-shaped, and have only a thin layer of compact bone surrounding a spongy interior. Short bones provide stability and support as well as some limited motion. Flat bones are thin and generally curved, with two parallel layers of compact bone sandwiching a layer of spongy bone. Most of the bones of the skull are flat bones, as is the sternum.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone: Gross anatomy', 'Sesamoid bones are bones embedded in tendons. Since they act to hold the tendon further away from the joint, the angle of the tendon is increased and thus the leverage of the muscle is increased. Irregular bones do not fit into the above categories. They consist of thin layers of compact bone surrounding a spongy interior. As implied by the name, their shapes are irregular and complicated. Often this irregular shape is due to their many centers of ossification or because they contain bony sinuses. The bones of the spine, pelvis, and some bones of the skull are irregular bones. Examples include the ethmoid and sphenoid bones.', 'Wikipedia: Bone', 'https://en.wikipedia.org/w/index.php?title=Bone&oldid=1380119203', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Sesamoid bones are bones embedded in tendons. Since they act to hold the tendon further away from the joint, the angle of the tendon is increased and thus the leverage of the muscle is increased. Irregular bones do not fit into the above categories. They consist of thin layers of compact bone surrounding a spongy interior. As implied by the name, their shapes are irregular and complicated. Often this irregular shape is due to their many centers of ossification or because they contain bony sinuses. The bones of the spine, pelvis, and some bones of the skull are irregular bones. Examples include the ethmoid and sphenoid bones.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone: Terminology', 'Anatomists use a number of anatomical terms to describe the appearance, shape and function of bones. Like other anatomical terms, many of these derive from Latin and Greek. Some anatomists still use Latin to refer to bones. The term "osseous", and the prefix "osteo-", referring to things related to bone, are still used commonly today. Some examples of terms used to describe bones include the term "foramen" to describe a hole through which something passes, and a "canal" or "meatus" to describe a tunnelure. A protrusion from a bone can be called a number of terms, including a "condyle", "crest", "spine", "eminence", "tubercle" or "tuberosity", depending on the protrusion''s shape and location. In general, long bones are said to have a "head", "neck", and "body". When two bones join, they are said to "articulate". If the two bones have a fibrous connection and are relatively immobile, then the joint is called a "suture".', 'Wikipedia: Bone', 'https://en.wikipedia.org/w/index.php?title=Bone&oldid=1380119203', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Anatomists use a number of anatomical terms to describe the appearance, shape and function of bones. Like other anatomical terms, many of these derive from Latin and Greek. Some anatomists still use Latin to refer to bones. The term "osseous", and the prefix "osteo-", referring to things related to bone, are still used commonly today. Some examples of terms used to describe bones include the term "foramen" to describe a hole through which something passes, and a "canal" or "meatus" to describe a tunnelure. A protrusion from a bone can be called a number of terms, including a "condyle", "crest", "spine", "eminence", "tubercle" or "tuberosity", depending on the protrusion''s shape and location. In general, long bones are said to have a "head", "neck", and "body". When two bones join, they are said to "articulate". If the two bones have a fibrous connection and are relatively immobile, then the joint is called a "suture".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone: Mechanical', 'Bones serve a variety of mechanical functions. Together the bones in the body form the skeleton. They provide a frame to keep the body supported, and an attachment point for skeletal muscles, tendons, ligaments and joints, which function together to generate and transfer forces so that individual body parts or the whole body can be manipulated in three-dimensional space (the interaction between bone and muscle is studied in biomechanics). Bones protect internal organs, such as the skull protecting the brain or the ribs protecting the heart and lungs. Because of the way that bone is formed, bone has a high compressive strength of about 170 MPa (1,700 kgf/cm2), poor tensile strength of 104–121 MPa, and a very low shear stress strength (51.6 MPa). This means that bone resists pushing (compressional) stress well, resist pulling (tensional) stress less well, but only poorly resists shear stress (such as due to torsional loads). While bone is essentially brittle, bone does have a significant degree of elasticity, contributed chiefly by collagen. Mechanically, bones also have a special role in hearing. The ossicles are three small bones in the middle ear which are involved in sound transduction.', 'Wikipedia: Bone', 'https://en.wikipedia.org/w/index.php?title=Bone&oldid=1380119203', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Bones serve a variety of mechanical functions. Together the bones in the body form the skeleton. They provide a frame to keep the body supported, and an attachment point for skeletal muscles, tendons, ligaments and joints, which function together to generate and transfer forces so that individual body parts or the whole body can be manipulated in three-dimensional space (the interaction between bone and muscle is studied in biomechanics). Bones protect internal organs, such as the skull protecting the brain or the ribs protecting the heart and lungs. Because of the way that bone is formed, bone has a high compressive strength of about 170 MPa (1,700 kgf/cm2), poor tensile strength of 104–121 MPa, and a very low shear stress strength (51.6 MPa). This means that bone resists pushing (compressional) stress well, resist pulling (tensional) stress less well, but only poorly resists shear stress (such as due to torsional loads). While bone is essentially brittle, bone does have a significant degree of elasticity, contributed chiefly by collagen. Mechanically, bones also have a special role in hearing. The ossicles are three small bones in the middle ear which are involved in sound transduction.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone: Synthetic', 'The cancellous part of bones contain bone marrow. Bone marrow produces blood cells in a process called hematopoiesis. Blood cells that are created in bone marrow include red blood cells, platelets and white blood cells. Progenitor cells such as the hematopoietic stem cell divide in a process called mitosis to produce precursor cells. These include precursors which eventually give rise to white blood cells, and erythroblasts which give rise to red blood cells. Unlike red and white blood cells, created by mitosis, platelets are shed from very large cells called megakaryocytes. This process of progressive differentiation occurs within the bone marrow. After the cells are matured, they enter the circulation. Every day, over 2.5 billion red blood cells and platelets, and 50–100 billion granulocytes are produced in this way. As well as creating cells, bone marrow is also one of the major sites where defective or aged red blood cells are destroyed.', 'Wikipedia: Bone', 'https://en.wikipedia.org/w/index.php?title=Bone&oldid=1380119203', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The cancellous part of bones contain bone marrow. Bone marrow produces blood cells in a process called hematopoiesis. Blood cells that are created in bone marrow include red blood cells, platelets and white blood cells. Progenitor cells such as the hematopoietic stem cell divide in a process called mitosis to produce precursor cells. These include precursors which eventually give rise to white blood cells, and erythroblasts which give rise to red blood cells. Unlike red and white blood cells, created by mitosis, platelets are shed from very large cells called megakaryocytes. This process of progressive differentiation occurs within the bone marrow. After the cells are matured, they enter the circulation. Every day, over 2.5 billion red blood cells and platelets, and 50–100 billion granulocytes are produced in this way. As well as creating cells, bone marrow is also one of the major sites where defective or aged red blood cells are destroyed.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone: Metabolic', 'Mineral storage – bones act as reserves of minerals important for the body, most notably calcium and phosphorus. Determined by the species, age, and the type of bone, bone cells make up to 15 percent of the bone. Growth factor storage—mineralized bone matrix stores important growth factors such as insulin-like growth factors, transforming growth factor, bone morphogenetic proteins and others. Fat storage – marrow adipose tissue (MAT) acts as a storage reserve of fatty acids. Acid-base balance – bone buffers the blood against excessive pH changes by absorbing or releasing alkaline salts. Detoxification – bone tissues can also store heavy metals and other foreign elements, removing them from the blood and reducing their effects on other tissues. These can later be gradually released for excretion. Endocrine organ – bone controls phosphate metabolism by releasing fibroblast growth factor 23 (FGF-23), which acts on kidneys to reduce phosphate reabsorption. Bone cells also release a hormone called osteocalcin, which contributes to the regulation of blood sugar (glucose) and fat deposition. Osteocalcin increases both the insulin secretion and sensitivity, in addition to boosting the number of insulin-producing cells and reducing stores of fat.', 'Wikipedia: Bone', 'https://en.wikipedia.org/w/index.php?title=Bone&oldid=1380119203', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Mineral storage – bones act as reserves of minerals important for the body, most notably calcium and phosphorus. Determined by the species, age, and the type of bone, bone cells make up to 15 percent of the bone. Growth factor storage—mineralized bone matrix stores important growth factors such as insulin-like growth factors, transforming growth factor, bone morphogenetic proteins and others. Fat storage – marrow adipose tissue (MAT) acts as a storage reserve of fatty acids. Acid-base balance – bone buffers the blood against excessive pH changes by absorbing or releasing alkaline salts. Detoxification – bone tissues can also store heavy metals and other foreign elements, removing them from the blood and reducing their effects on other tissues. These can later be gradually released for excretion. Endocrine organ – bone controls phosphate metabolism by releasing fibroblast growth factor 23 (FGF-23), which acts on kidneys to reduce phosphate reabsorption. Bone cells also release a hormone called osteocalcin, which contributes to the regulation of blood sugar (glucose) and fat deposition. Osteocalcin increases both the insulin secretion and sensitivity, in addition to boosting the number of insulin-producing cells and reducing stores of fat.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone remodeling', 'In osteology, bone remodeling or bone metabolism is a lifelong process where mature bone tissue is removed from the skeleton (a process called bone resorption) and new bone tissue is formed (a process called ossification or new bone formation). Recent research has identified a specialised subset of blood vessels, termed Type R endothelial cells, in the bone microenvironment. These blood vessels play a crucial role in adult bone remodelling by mediating interactions between bone-resorbing osteoclasts and bone-forming osteoblasts. Type R blood vessels are characterised by their association with post-arterial capillaries and exhibit unique remodelling properties crucial for bone homeostasis. These processes also control the reshaping or replacement of bone following injuries like fractures but also micro-damage, which occurs during normal activity. Remodeling responds also to functional demands of the mechanical loading. In the first year of life, almost 100% of the skeleton is replaced. In adults, remodeling proceeds at about 10% per year. An imbalance in the regulation of bone remodeling''s two sub-processes, bone resorption and bone formation, results in many metabolic bone diseases, such as osteoporosis.', 'Wikipedia: Bone remodeling', 'https://en.wikipedia.org/w/index.php?title=Bone_remodeling&oldid=1353474130', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'In osteology, bone remodeling or bone metabolism is a lifelong process where mature bone tissue is removed from the skeleton (a process called bone resorption) and new bone tissue is formed (a process called ossification or new bone formation). Recent research has identified a specialised subset of blood vessels, termed Type R endothelial cells, in the bone microenvironment. These blood vessels play a crucial role in adult bone remodelling by mediating interactions between bone-resorbing osteoclasts and bone-forming osteoblasts. Type R blood vessels are characterised by their association with post-arterial capillaries and exhibit unique remodelling properties crucial for bone homeostasis. These processes also control the reshaping or replacement of bone following injuries like fractures but also micro-damage, which occurs during normal activity. Remodeling responds also to functional demands of the mechanical loading. In the first year of life, almost 100% of the skeleton is replaced. In adults, remodeling proceeds at about 10% per year. An imbalance in the regulation of bone remodeling''s two sub-processes, bone resorption and bone formation, results in many metabolic bone diseases, such as osteoporosis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Bone remodeling: Physiology', 'Bone homeostasis involves multiple but coordinated cellular and molecular events. Two main types of cells are responsible for bone metabolism: osteoblasts (which secrete new bone), and osteoclasts (which break bone down). The structure of bones as well as adequate supply of calcium requires close cooperation between these two cell types and other cell populations present at the bone remodeling sites (e.g. immune cells). Bone metabolism relies on complex signaling pathways and control mechanisms to achieve proper rates of growth and differentiation. These controls include the action of several hormones, including parathyroid hormone (PTH), vitamin D, growth hormone, steroids, and calcitonin, as well as several bone marrow-derived membrane and soluble cytokines and growth factors (e.g. M-CSF, RANKL, VEGF and IL-6 family). It is in this way that the body is able to maintain proper levels of calcium required for physiological processes. Thus bone remodeling is not just occasional "repair of bone damage" but rather an active, continual process that is always happening in a healthy body. Subsequent to appropriate signaling, osteoclasts move to resorb the surface of the bone, followed by deposition of bone by osteoblasts. Together, the cells that are responsible for bone remodeling are known as the basic multicellular unit (BMU), and the temporal duration (i.e. lifespan) of the BMU is referred to as the bone remodeling period.', 'Wikipedia: Bone remodeling', 'https://en.wikipedia.org/w/index.php?title=Bone_remodeling&oldid=1353474130', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Bone homeostasis involves multiple but coordinated cellular and molecular events. Two main types of cells are responsible for bone metabolism: osteoblasts (which secrete new bone), and osteoclasts (which break bone down). The structure of bones as well as adequate supply of calcium requires close cooperation between these two cell types and other cell populations present at the bone remodeling sites (e.g. immune cells). Bone metabolism relies on complex signaling pathways and control mechanisms to achieve proper rates of growth and differentiation. These controls include the action of several hormones, including parathyroid hormone (PTH), vitamin D, growth hormone, steroids, and calcitonin, as well as several bone marrow-derived membrane and soluble cytokines and growth factors (e.g. M-CSF, RANKL, VEGF and IL-6 family). It is in this way that the body is able to maintain proper levels of calcium required for physiological processes. Thus bone remodeling is not just occasional "repair of bone damage" but rather an active, continual process that is always happening in a healthy body. Subsequent to appropriate signaling, osteoclasts move to resorb the surface of the bone, followed by deposition of bone by osteoblasts. Together, the cells that are responsible for bone remodeling are known as the basic multicellular unit (BMU), and the temporal duration (i.e. lifespan) of the BMU is referred to as the bone remodeling period.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Human skin', 'The human skin is the outer covering of the body and is the largest organ of the integumentary system. The skin has up to seven layers of ectodermal tissue guarding muscles, bones, ligaments and internal organs. Human skin is similar to most of the other mammals'' skin, and it is very similar to pig skin. Though nearly all human skin is covered with hair follicles, it can appear hairless. There are two general types of skin: hairy and glabrous skin (hairless). The adjective cutaneous literally means "of the skin" (from Latin cutis, skin). Skin plays an important immunity role in protecting the body against pathogens and excessive water loss. Its other functions are insulation, temperature regulation, sensation, synthesis of vitamin D, and the protection of vitamin B folates. Severely damaged skin will try to heal by forming scar tissue. This is often discoloured and depigmented. In humans, skin pigmentation (affected by melanin) varies among populations, and skin type can range from dry to non-dry and from oily to non-oily. Such skin variety provides a rich and diverse habitat for the approximately one thousand species of bacteria from nineteen phyla which have been found on human skin.', 'Wikipedia: Human skin', 'https://en.wikipedia.org/w/index.php?title=Human_skin&oldid=1356788707', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The human skin is the outer covering of the body and is the largest organ of the integumentary system. The skin has up to seven layers of ectodermal tissue guarding muscles, bones, ligaments and internal organs. Human skin is similar to most of the other mammals'' skin, and it is very similar to pig skin. Though nearly all human skin is covered with hair follicles, it can appear hairless. There are two general types of skin: hairy and glabrous skin (hairless). The adjective cutaneous literally means "of the skin" (from Latin cutis, skin). Skin plays an important immunity role in protecting the body against pathogens and excessive water loss. Its other functions are insulation, temperature regulation, sensation, synthesis of vitamin D, and the protection of vitamin B folates. Severely damaged skin will try to heal by forming scar tissue. This is often discoloured and depigmented. In humans, skin pigmentation (affected by melanin) varies among populations, and skin type can range from dry to non-dry and from oily to non-oily. Such skin variety provides a rich and diverse habitat for the approximately one thousand species of bacteria from nineteen phyla which have been found on human skin.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Human skin: Structure', 'Human skin shares anatomical, physiological, biochemical and immunological properties with other mammalian lines. Pig skin especially shares similar epidermal and dermal thickness ratios to human skin: pig and human skin share similar hair follicle and blood vessel patterns; biochemically the dermal collagen and elastin content is similar in pig and human skin; and pig skin and human skin have similar physical responses to various growth factors. Skin has mesodermal cells which produce pigmentation, such as melanin provided by melanocytes, which absorb some of the potentially dangerous ultraviolet radiation (UV) in sunlight. It contains DNA repair enzymes that help reverse UV damage. People lacking the genes for these enzymes have high rates of skin cancer. One form predominantly produced by UV light, melanoma, is particularly invasive, causing it to spread quickly, and can often be deadly. Human skin pigmentation varies substantially between populations; this has led to the classification of people(s) on the basis of skin colour.', 'Wikipedia: Human skin', 'https://en.wikipedia.org/w/index.php?title=Human_skin&oldid=1356788707', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'Human skin shares anatomical, physiological, biochemical and immunological properties with other mammalian lines. Pig skin especially shares similar epidermal and dermal thickness ratios to human skin: pig and human skin share similar hair follicle and blood vessel patterns; biochemically the dermal collagen and elastin content is similar in pig and human skin; and pig skin and human skin have similar physical responses to various growth factors. Skin has mesodermal cells which produce pigmentation, such as melanin provided by melanocytes, which absorb some of the potentially dangerous ultraviolet radiation (UV) in sunlight. It contains DNA repair enzymes that help reverse UV damage. People lacking the genes for these enzymes have high rates of skin cancer. One form predominantly produced by UV light, melanoma, is particularly invasive, causing it to spread quickly, and can often be deadly. Human skin pigmentation varies substantially between populations; this has led to the classification of people(s) on the basis of skin colour.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Human skin: Structure', 'The skin is the largest organ in the human body, comprising roughly 16% of body mass. The skin has the second largest surface area in the human body (the inner lining of the intestinal tract is 15 to 20 times larger). For the average adult human, the skin has a surface area of 1.5–2.0 square metres (16–22 sq ft). The thickness of the skin varies considerably over all parts of the body, and between men and women, and young and old. An example is the skin on the forearm, which is on average 1.3 mm in males and 1.26 mm in females. One average square inch (6.5 cm2) of skin holds 650 sweat glands, 20 blood vessels, 60,000 melanocytes, and more than 1,000 nerve endings. The average human skin cell is about 30 μm in diameter, ranging from 25 to 40 μm2, depending on a variety of factors. Skin is composed of three primary layers: the epidermis, the dermis and the hypodermis (more commonly called the subcutaneous layer).', 'Wikipedia: Human skin', 'https://en.wikipedia.org/w/index.php?title=Human_skin&oldid=1356788707', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The skin is the largest organ in the human body, comprising roughly 16% of body mass. The skin has the second largest surface area in the human body (the inner lining of the intestinal tract is 15 to 20 times larger). For the average adult human, the skin has a surface area of 1.5–2.0 square metres (16–22 sq ft). The thickness of the skin varies considerably over all parts of the body, and between men and women, and young and old. An example is the skin on the forearm, which is on average 1.3 mm in males and 1.26 mm in females. One average square inch (6.5 cm2) of skin holds 650 sweat glands, 20 blood vessels, 60,000 melanocytes, and more than 1,000 nerve endings. The average human skin cell is about 30 μm in diameter, ranging from 25 to 40 μm2, depending on a variety of factors. Skin is composed of three primary layers: the epidermis, the dermis and the hypodermis (more commonly called the subcutaneous layer).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Human skin: Epidermis', 'The epidermis, "epi" coming from the Greek language meaning "over" or "upon", is the outermost layer of the skin. It forms the waterproof, protective wrap over the body''s surface, which also serves as a barrier to infection and is made up of stratified squamous epithelium with an underlying basal lamina.', 'Wikipedia: Human skin', 'https://en.wikipedia.org/w/index.php?title=Human_skin&oldid=1356788707', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The epidermis, "epi" coming from the Greek language meaning "over" or "upon", is the outermost layer of the skin. It forms the waterproof, protective wrap over the body''s surface, which also serves as a barrier to infection and is made up of stratified squamous epithelium with an underlying basal lamina.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Human skin: Epidermis', 'The epidermis contains no blood vessels, and cells in the deepest layers are nourished almost exclusively by diffused oxygen from the surrounding air and to a far lesser degree by blood capillaries extending to the outer layers of the dermis. The main type of cells that make up the epidermis are Merkel cells, keratinocytes, with melanocytes and Langerhans cells also present. The epidermis can be further subdivided into the following strata (beginning with the outermost layer): corneum, lucidum (only in palms of hands and bottoms of feet), granulosum, spinosum, and basale. Cells are formed through mitosis at the basale layer. The daughter cells (see cell division) move up the strata changing shape and composition as they die due to isolation from their blood source. The cytoplasm is released and the protein keratin is inserted. They eventually reach the corneum and slough off (desquamation). This process is called "keratinization". This keratinized layer of skin is responsible for keeping water in the body and keeping other harmful chemicals and pathogens out, making skin a natural barrier to infection.', 'Wikipedia: Human skin', 'https://en.wikipedia.org/w/index.php?title=Human_skin&oldid=1356788707', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The epidermis contains no blood vessels, and cells in the deepest layers are nourished almost exclusively by diffused oxygen from the surrounding air and to a far lesser degree by blood capillaries extending to the outer layers of the dermis. The main type of cells that make up the epidermis are Merkel cells, keratinocytes, with melanocytes and Langerhans cells also present. The epidermis can be further subdivided into the following strata (beginning with the outermost layer): corneum, lucidum (only in palms of hands and bottoms of feet), granulosum, spinosum, and basale. Cells are formed through mitosis at the basale layer. The daughter cells (see cell division) move up the strata changing shape and composition as they die due to isolation from their blood source. The cytoplasm is released and the protein keratin is inserted. They eventually reach the corneum and slough off (desquamation). This process is called "keratinization". This keratinized layer of skin is responsible for keeping water in the body and keeping other harmful chemicals and pathogens out, making skin a natural barrier to infection.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Human skin: Sublayers', 'Blood capillaries are found beneath the epidermis and are linked to an arteriole and a venule. Arterial shunt vessels may bypass the network in ears, the nose and fingertips.', 'Wikipedia: Human skin', 'https://en.wikipedia.org/w/index.php?title=Human_skin&oldid=1356788707', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
