insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Human skin: Genes and proteins expressed in the epidermis', 'About 70% of all human protein-coding genes are expressed in the skin. Almost 500 genes have an elevated pattern of expression in the skin. There are fewer than 100 genes that are specific for the skin, and these are expressed in the epidermis. An analysis of the corresponding proteins show that these are mainly expressed in keratinocytes and have functions related to squamous differentiation and cornification.', 'Wikipedia: Human skin', 'https://en.wikipedia.org/w/index.php?title=Human_skin&oldid=1356788707', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'About 70% of all human protein-coding genes are expressed in the skin. Almost 500 genes have an elevated pattern of expression in the skin. There are fewer than 100 genes that are specific for the skin, and these are expressed in the epidermis. An analysis of the corresponding proteins show that these are mainly expressed in keratinocytes and have functions related to squamous differentiation and cornification.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'muscle-bone-skin', 'Human skin: Dermis', 'The dermis is the layer of skin beneath the epidermis that consists of connective tissue and cushions the body from stress and strain. The dermis is tightly connected to the epidermis by a basement membrane. It also harbours many nerve endings that provide the sense of touch and heat. It contains the hair follicles, sweat glands, sebaceous glands, apocrine glands, lymphatic vessels and blood vessels. The blood vessels in the dermis provide nourishment and waste removal from its own cells as well as from the stratum basale of the epidermis. The dermis is structurally divided into two areas: a superficial area adjacent to the epidermis, called the papillary region, and a deep thicker area known as the reticular region.', 'Wikipedia: Human skin', 'https://en.wikipedia.org/w/index.php?title=Human_skin&oldid=1356788707', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'muscle-bone-skin' and body = 'The dermis is the layer of skin beneath the epidermis that consists of connective tissue and cushions the body from stress and strain. The dermis is tightly connected to the epidermis by a basement membrane. It also harbours many nerve endings that provide the sense of touch and heat. It contains the hair follicles, sweat glands, sebaceous glands, apocrine glands, lymphatic vessels and blood vessels. The blood vessels in the dermis provide nourishment and waste removal from its own cells as well as from the stratum basale of the epidermis. The dermis is structurally divided into two areas: a superficial area adjacent to the epidermis, called the papillary region, and a deep thicker area known as the reticular region.');
